/* 화면 배율(Ctrl+휠)·창 크기 변경 뒤 가로로 밀린 화면을 원위치: 이 앱은 가로 스크롤이 없으므로 항상 왼쪽 0 */
function fixHScroll(){ try{ if(window.scrollX) window.scrollTo(0,window.scrollY); [document.documentElement,document.body,document.querySelector('.app')].forEach(e=>{ if(e&&e.scrollLeft) e.scrollLeft=0; }); }catch(e){} }
window.addEventListener('resize',()=>{ fixHScroll(); requestAnimationFrame(fixHScroll); setTimeout(fixHScroll,120); });
