let RC_USE=false;
function rcPull(btnId){ RC_USE=true; try{ $(btnId).click(); } finally{ RC_USE=false; } }
[['mkt-rc','mkt-load'],['fx-rc','fx-mkt-btn'],['opt-rc','opt-rate-mkt'],['cb-rc','cb-mkt-btn']].forEach(([a,b])=>{ const el=$(a); if(el) el.addEventListener('click',()=>rcPull(b)); });
/* 날짜 입력 + 년·월·일 선택 묶음 (과거·미래 모두 선택) */
function ymdBind(id,onChange){
  const di=$(id+'-date'), ys=$(id+'-y'), ms=$(id+'-m'), dd=$(id+'-d'), pad=n=>String(n).padStart(2,'0');
  function sync(d){ if(!d) return; const ty=new Date().getFullYear(), [y,m,x]=d.split('-').map(Number), yF=Math.min(1990,y), yT=Math.max(ty+30,y);
    if(ys.dataset.r!==yF+'-'+yT){ ys.innerHTML=Array.from({length:yT-yF+1},(_,i)=>`<option value="${yT-i}">${yT-i}년</option>`).join(''); ys.dataset.r=yF+'-'+yT; }
    if(!ms.options.length) ms.innerHTML=Array.from({length:12},(_,i)=>`<option value="${i+1}">${i+1}월</option>`).join('');
    const dim=new Date(Date.UTC(y,m,0)).getUTCDate(); if(dd.options.length!==dim) dd.innerHTML=Array.from({length:dim},(_,i)=>`<option value="${i+1}">${i+1}일</option>`).join('');
    di.value=d; ys.value=String(y); ms.value=String(m); dd.value=String(Math.min(x,dim)); }
  di.addEventListener('change',()=>{ if(di.value){ sync(di.value); onChange&&onChange(di.value); } });
  [ys,ms,dd].forEach(el=>el.addEventListener('change',()=>{ const y=+ys.value, m=+ms.value, dim=new Date(Date.UTC(y,m,0)).getUTCDate(), d=`${y}-${pad(m)}-${pad(Math.min(+dd.value||1,dim))}`; sync(d); onChange&&onChange(d); }));
  return {sync};
}
function prsRcHint(){ const d=$('prs-rc-date').value, k=d?rcKey(d):null;
  $('prs-rc-h').innerHTML=!d?'':!k?`<span class="warn">${d}은(는) 공통 금리커브 보관 자료(${rcRange()})보다 앞섭니다.</span>`
    : k===d?`${d} 공통 금리커브 자료를 가져옵니다.`:`${d}에는 보관 자료가 없어 가장 가까운 이전 보관일 <b>${k}</b> 자료를 가져옵니다.`; }
