const RC_PRS_T=[0.25,0.5,0.75,1,1.5,2,2.5,3,4,5,7,10], RC_CB_T=[0.25,0.5,0.75,1,2,3,5,10,20,30];
$('cb-cs-grade').innerHTML=CurveJS.GRADES.map(g=>`<option${g==='A'?' selected':''}>${g}</option>`).join('');
$('cb-cs-btn').addEventListener('click',()=>{
  const c=state.cb, d=c.valuation, gr=$('cb-cs-grade').value, msg=$('cb-cs-msg');
  if(!d||!c.maturity||c.maturity<=d){ msg.innerHTML='<span class="warn">평가일과 만기일을 먼저 입력하세요.</span>'; return; }
  let gk,gg; try{ gk=rcCurve('ktb',d); gg=rcCurve(gr,d); }catch(e){ msg.innerHTML=`<span class="warn">${e.message}</span>`; return; }
  if(!gk||!gg){ msg.innerHTML=`<span class="warn">평가일 ${d}이 공통 금리커브 자료보다 앞섭니다. 보관된 자료: ${rcRange()}</span>`; return; }
  const T=(Date.parse(c.maturity)-Date.parse(d))/864e5/365, zg=CurveJS.zeroAt(gg.c,T), zk=CurveJS.zeroAt(gk.c,T);
  c.credit_spread=+(zg-zk).toFixed(8); fillForm(); save(); recompute();
  msg.innerHTML=`<span>잔존만기 T=${T.toFixed(2)}년 제로금리 · 회사채 ${gr} <b>${pct(zg,3)}</b> − 국고채 <b>${pct(zk,3)}</b> = 신용스프레드 <b>${((zg-zk)*1e4).toFixed(1)}bp</b> (${rcSrcNote(gk)})</span><span class="hint">사채 계산기는 국고채 spot에 이 스프레드를 더해 할인합니다. 등급 커브와 국고채 커브는 같은 날짜 자료입니다.</span>`;
});

$('mkt-range').textContent = `수집 기간 · KRW ${first(MARKET.krw)} ~ ${last(MARKET.krw)} · USD ${first(MARKET.usd)} ~ ${last(MARKET.usd)}`;
$('mkt-date').value = (state.curve.src && state.curve.src.asked) || last(MARKET.krw);
$('mkt-date').min = first(MARKET.usd);
$('mkt-load').addEventListener('click', ()=>{
  const d=$('mkt-date').value, st=$('mkt-status');
  if(!d){ st.innerHTML='<span class="warn">기준일을 고르세요.</span>'; return; }
  const sel=rcPick('curve.pick_krw','ktb'), selU=rcPick('curve.pick_usd','ust');
  if(RC_USE){
    let g,u; try{ g=rcCurve(sel,d); u=rcCurve(selU,d); }catch(e){ st.innerHTML=`<span class="warn">${e.message}</span>`; return; }
    if(!g||!u){ st.innerHTML=`<span class="warn">공통 금리커브 자료보다 앞선 날짜입니다. 보관된 자료: ${rcRange()}</span>`; return; }
    state.curve.krw=PAR_TENORS.map(t=>CurveJS.parAt(g.c,t)); state.curve.usd=PAR_TENORS.map(t=>CurveJS.parAt(u.c,t));
    state.curve.src={krw:g.key, usd:u.key, asked:d, krw_name:rcLabel(sel), usd_name:rcLabel(selU)};
    const sv=$('mkt-setval').checked; if(sv){ state.irs.valuation=d; state.crs.valuation=d; fillForm(); }
    save(); recompute();
    st.innerHTML=`<span>공통 커브 KRW 열 <b>${rcLabel(sel)}</b> (${rcSrcNote(g)}) · USD 열 <b>${rcLabel(selU)}</b> (${rcSrcNote(u)})의 par 금리를 넣었습니다${sv?' (평가일도 변경)':''}.</span><span class="hint">금리 스왑 계산기는 이 par 금리를 엑셀 모형과 같은 방식(연 1회 이표)으로 다시 부트스트랩합니다.</span>`+(g.key!==d?`<span class="hint">${d}에 자료가 없어 직전 자료 ${g.key}를 썼습니다.</span>`:'');
    return;
  }
  const ik=lookupIdx(MARKET.krw,d), iu=lookupIdx(MARKET.usd,d);
  if(ik<0||iu<0){ st.innerHTML=`<span class="warn">${d}은(는) 수집 기간보다 앞섭니다. ${first(MARKET.krw)} 이후 날짜를 고르세요.</span>`; return; }
  const dk=MARKET.krw.dates[ik], du=MARKET.usd.dates[iu];
  state.curve.krw = fixPar(MARKET.krw.rates[ik].slice());
  state.curve.usd = fixPar(MARKET.usd.rates[iu].slice());
  state.curve.src = {krw:dk, usd:du, asked:d};
  const setVal = $('mkt-setval').checked;
  if(setVal){ state.irs.valuation=d; state.crs.valuation=d; fillForm(); }
  save(); recompute();
  const notes=[];
  if(dk!==d) notes.push(`KRW는 ${d}에 고시값이 없어 직전 영업일 ${dk} 값을 썼습니다.`);
  if(du!==d) notes.push(`USD는 ${d}에 고시값이 없어 직전 영업일 ${du} 값을 썼습니다.`);
  st.innerHTML = `<span>KRW <b>${dk}</b> · USD <b>${du}</b> 커브를 적용했습니다${setVal?' (평가일도 변경)':''}.</span>` + notes.map(n=>`<span class="hint">${n}</span>`).join('');
});

let seq=0;
async function recompute(){
  const my=++seq; normPar();
  try{ syncVals(); }catch(e){}
  if(VIEW==='option'){ try{ await renderOpt(my); }catch(e){ showErr('opt-err','계산 오류: '+e.message); console.log(e); } repAfter(); return; }
  if(VIEW==='prs'){ try{ await renderPrs(my); }catch(e){ showErr('prs-err','계산 오류: '+((e&&e.message)||e)); console.log(e); } repAfter(); return; }
  if(VIEW==='fx'){ try{ await renderFx(my); }catch(e){ showErr('fx-err','계산 오류: '+((e&&e.message)||e)); console.log(e); } repAfter(); return; }
  if(VIEW==='cb'){ try{ await renderCb(my); }catch(e){ showErr('cb-err','계산 오류: '+((e&&e.message)||e)); console.log(e); } repAfter(); return; }
  if(VIEW==='home') return;
  if(VIEW==='fin'){ try{ renderFin(); }catch(e){ console.log(e); } return; }
  if(VIEW==='rates'){ try{ await renderRates(); }catch(e){ console.log(e); $('rc-err').textContent='계산 오류: '+((e&&e.message)||e); $('rc-err').hidden=false; } return; }
  renderSrc(); renderCurve();
  try{ await renderIRS(my); }catch(e){ showErr('irs-err','계산 오류: '+e.message); }
  try{ await renderCRS(my); }catch(e){ showErr('crs-err','계산 오류: '+e.message); }
  repAfter();
}


