const LAST={irs:null,crs:null,opt:null,prs:null,cb:null,fx:null};
let DL=null, xlsxLoading=null;
const XLSX_SRC = 'vendor/xlsx.full.min.js'; // 오프라인에서도 되도록 앱에 포함 (SheetJS 0.18.5)
function loadXLSX(){ if(window.XLSX) return Promise.resolve(); return xlsxLoading = xlsxLoading || new Promise((ok,no)=>{ const s=document.createElement('script'); s.src=XLSX_SRC; s.onload=ok; s.onerror=()=>{ xlsxLoading=null; no(new Error('엑셀 라이브러리를 불러오지 못했습니다')); }; document.head.appendChild(s); }); }
function xlStatus(msg){ const el=$('xlsx-status'); el.hidden=!msg; el.textContent=msg||''; }
(async()=>{
  if(IS_DESKTOP){ $('xlsx-btn').hidden=false; return; }
  for(let i=0;i<20 && !(window.claude&&window.claude.use);i++) await new Promise(r=>setTimeout(r,250));
  try{ DL = window.claude&&window.claude.use ? await window.claude.use('downloads') : null; }catch(e){ DL=null; }
  $('xlsx-btn').hidden=!DL;
})();
const F={krw:'#,##0;[Red]-#,##0', usd:'#,##0.00;[Red]-#,##0.00', pct:'0.0000%', bp:'0.0', df:'0.000000', dcf:'0.0000', fx:'#,##0.00'};
function sheet(rows, widths){
  // rows: arrays of cells; a cell may be {v, z} for a number format
  const aoa=rows.map(r=>r.map(c=> (c&&typeof c==='object'&&'v' in c)? c.v : c));
  const ws=XLSX.utils.aoa_to_sheet(aoa);
  rows.forEach((r,i)=>r.forEach((c,j)=>{ if(c&&typeof c==='object'&&'z' in c){ const a=XLSX.utils.encode_cell({r:i,c:j}); if(ws[a]) ws[a].z=c.z; } }));
  if(widths) ws['!cols']=widths.map(w=>({wch:w}));
  return ws;
}
const n=(v,z)=>({v:(v==null||!isFinite(v))?null:v, z});
const d=s=>s; // ISO 날짜 문자열 그대로 (엑셀에서 텍스트)
function cfRows(rows, cur, withFwd){
  const zf = cur==='USD'?F.usd:F.krw;
  const head=['No','시작일','종료일','일수','DCF','T(년)','Zero','DF'].concat(withFwd?['Fwd Rate']:[]).concat([`CF (${cur})`,`PV (${cur})`]);
  return [head].concat(rows.map(r=>[r.no,d(r.start),d(r.end),r.days,n(r.dcf,F.dcf),n(r.t,'0.0000'),n(r.zero,F.pct),n(r.df,F.df)].concat(withFwd?[n(r.fwd,F.pct)]:[]).concat([n(r.cf,zf),n(r.pv,zf)])));
}
