  const kp=shifted(state.curve.krw,shift.krw), up=shifted(state.curve.usd,shift.usd), bk=SwapJS.bootstrap(kp), bu=SwapJS.bootstrap(up);
  const cr=[['Tenor(Y)','KRW Par','KRW Zero','USD Par','USD Zero']].concat(PAR_TENORS.map((tn,i)=>[tn,n(kp[i],F.pct),n(bk.zero_by_tenor[tn],F.pct),n(up[i],F.pct),n(bu.zero_by_tenor[tn],F.pct)]));
