  $('sv-body').querySelectorAll('[data-load]').forEach(b=>b.addEventListener('click',()=>{ const r=Saves.list.find(x=>x.id===b.dataset.load); if(!r) return; svClose(); renderSaves(k,gk(r),r.id); loadSave(k,r.id); }));
