    const rows=[[`${KIND_NAME[k]} · 평가보고서 비교 (차이 = 계산기 − 보고서)`],[],head];
    rs.forEach(r=>{ const x=repRows(k,r.summary,r.report), line=[glabel(r),r.author||'',r.valuation,r.report.firm||'',r.report.date||''];
      x.forEach(o=>{ line.push(o.c,o.r,o.d==null?null:(o.f.pct?o.d*100:o.d)); if(!o.f.pct) line.push(o.rt==null?null:{v:o.rt,t:'n',z:'0.00%'}); }); rows.push(line); });
    const wb=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, sheet(rows,[24,10,12,16,14].concat(head.slice(5).map(()=>16))), '보고서 비교');
