const IO_FORMAT='derivative-valuator-evaluations', IO_VERSION=1;
function cyrb53(str,seed=0){ let h1=0xdeadbeef^seed,h2=0x41c6ce57^seed; for(let i=0,ch;i<str.length;i++){ ch=str.charCodeAt(i); h1=Math.imul(h1^ch,2654435761); h2=Math.imul(h2^ch,1597334677); }
  h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909); h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909); return (4294967296*(2097151&h2)+(h1>>>0)).toString(36); }
const cleanFile=s=>String(s).replace(/[\\/:*?"<>|\s]+/g,'_').replace(/_+/g,'_').slice(0,80);
async function saveTextFile(name,text,say){
  if(IS_DESKTOP && window.pywebview && window.pywebview.api && window.pywebview.api.save_text){
    const path=await window.pywebview.api.save_text(name,text); say(path?'저장했습니다: '+path:'저장을 취소했습니다.'); return; }
  if(DL){ try{ await DL.save({filename:name,data:new Blob([text],{type:'application/json'})}); say('내려받았습니다: '+name); }
    catch(e){ const c=e&&e.code; say(c==='declined'?'저장을 취소했습니다.':c==='rate_limited'?'저장 창이 이미 열려 있습니다. 잠시 후 다시 눌러 주세요.':'파일을 저장하지 못했습니다: '+((e&&e.message)||e)); } return; }
  // 그 밖의 브라우저: 내려받기 링크
  try{ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([text],{type:'application/json'})); a.download=name; document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); },1000); say('내려받았습니다: '+name); }
  catch(e){ say('이 화면에서는 파일 저장을 쓸 수 없습니다.'); }
}
function exportRecs(recs,label,say){
  if(!USER.name){ openGate(false); return; }
  say=say||(m=>{ $('sv-msg').innerHTML=`<span>${esc(m)}</span>`; });
  const records=recs.map(r=>({kind:r.kind,name:r.name,valuation:r.valuation,savedAt:r.savedAt,author:r.author||USER.name,author_uid:r.author_uid||USER.uid,
    imported_from:r.imported?(r.imported_from||null):null,inputs:r.inputs,curve:r.curve,shift:r.shift||{},summary:r.summary,report:r.report||null}));
  const body=JSON.stringify(records);
  const payload={format:IO_FORMAT,version:IO_VERSION,app:'Financial Calculator',exported_at:new Date().toISOString(),exporter:{name:USER.name,uid:USER.uid},count:records.length,checksum:cyrb53(body),records};
  const d=new Date(), ds=`${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
  saveTextFile(`${cleanFile(label)}_${ds}_${cleanFile(USER.name)}.json`, JSON.stringify(payload,null,1), say);
}
