// 다시 계산 (JS 엔진, 화면 상태를 잠시 바꿨다가 되돌림)
function recalcRecord(r){
  const k=r.kind, keepK=state[k], keepC=state.curve;
  try{
    state[k]=clone(r.inputs); if(r.curve&&(k==='irs'||k==='crs')) state.curve=clone(r.curve);
    if(k==='cb') cbMigrate(state.cb);
    if(k==='irs'){ const b={...state.irs,par_rates:shifted(state.curve.krw,r.shift?.krw||0)}; return SwapJS.irs(b).npv; }
    if(k==='crs'){ const b={...state.crs,krw_par_rates:shifted(state.curve.krw,r.shift?.krw||0),usd_par_rates:shifted(state.curve.usd,r.shift?.usd||0)}; return SwapJS.crs(b).npv; }
    if(k==='fx') return SwapJS.fx(fxParams()).value;
    if(k==='prs') return PrsJS.value(prsParams(),false).fv;
    if(k==='cb') return CbJS.value(cbParams(),false).total_amt;
    if(k==='opt'){ const {p}=optParams(); return OptionJS.value(p).price*(p.quantity||1); }
  }catch(e){ return null; } finally{ state[k]=keepK; state.curve=keepC; }
  return null;
}
