/* ───────── 옵션 계산기 ───────── */
const oshift={s:0,v:0};
const fmtPct=v=>(v>0?'+':v<0?'−':'')+Math.abs(v)+'%', fmtPp=v=>(v>0?'+':v<0?'−':'')+Math.abs(v)+'%p';
const won2=v=>nf2.format(v)+'원', wonT=v=>(Math.abs(v)>=1e6?nf0.format(v):nf2.format(v))+'원';
function syncOShift(){ $('opt-sim-s').value=oshift.s; $('opt-sim-v').value=oshift.v; $('opt-sim-s-out').textContent=fmtPct(oshift.s); $('opt-sim-v-out').textContent=fmtPp(oshift.v);  if(typeof syncVals==='function') syncVals(); }
document.querySelectorAll('input[data-oshift]').forEach(el=>el.addEventListener('input',()=>{ oshift[el.dataset.oshift]=+el.value; syncOShift(); scheduleFast(); }));
document.querySelectorAll('.onudge').forEach(btn=>{
  const el=$(btn.dataset.for), key=el.dataset.oshift, d=+btn.dataset.nudge*(+el.step||1); let t1=0,t2=0;
  const step=()=>{ const v=Math.max(+el.min,Math.min(+el.max,Math.round((oshift[key]+d)*10)/10)); if(v===oshift[key]) return; oshift[key]=v; syncOShift(); scheduleFast(); };
  const stop=()=>{ clearTimeout(t1); clearInterval(t2); t1=t2=0; };
  btn.addEventListener('pointerdown',e=>{ e.preventDefault(); stop(); step(); t1=setTimeout(()=>{ t2=setInterval(step,70); },400); });
  ['pointerup','pointerleave','pointercancel','blur'].forEach(ev=>btn.addEventListener(ev,stop));
  btn.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); step(); } });
  btn.addEventListener('contextmenu',e=>e.preventDefault());
});
$('opt-sim-reset').addEventListener('click',()=>{ oshift.s=0; oshift.v=0; syncOShift(); recompute(); });
// 종가 붙여넣기: 줄바꿈·탭·공백·세미콜론으로 구분, 숫자 안의 쉼표는 천 단위로 보고 제거
function parsePrices(txt){ return txt.split(/[\s;]+/).map(s=>s.replace(/,/g,'')).filter(s=>s!==''&&isFinite(+s)).map(Number); }
$('opt-prices').addEventListener('input',()=>{ state.opt.prices=parsePrices($('opt-prices').value); save(); schedule(); });
function fillPrices(){ if(document.activeElement!==$('opt-prices')) $('opt-prices').value=(state.opt.prices||[]).map(v=>+(+v).toFixed(6)).join('\n'); }
// 옵션 잔존만기(T)에 맞는 무위험금리: 실제 고시 만기만 써서 선형보간
//  T<1년: CD 91일물(0.25년)~국고채 1년 사이 보간, 단리 관행 / T≥1년: 국고채 1·2·3·5·10·20·30년 보간, 연 2회 복리 관행
const RF_NODES=[[0.25,0,'CD 91일'],[1,2,'국고채 1년'],[2,3,'국고채 2년'],[3,4,'국고채 3년'],[5,6,'국고채 5년'],[10,8,'국고채 10년'],[20,10,'국고채 20년'],[30,11,'국고채 30년']];
function rfForT(row,T){
  const N=RF_NODES.map(([t,idx,name])=>({t,v:row[idx],name}));
  if(T<=N[0].t) return {v:N[0].v, how:`${N[0].name} ${pct(N[0].v,3)} (만기가 3개월 이하라 그대로 사용)`};
  if(T>=N[N.length-1].t) return {v:N[N.length-1].v, how:`${N[N.length-1].name} ${pct(N[N.length-1].v,3)} (30년 초과는 30년물 사용)`};
  for(let k=0;k<N.length-1;k++){ const a=N[k], b=N[k+1];
    if(T>=a.t && T<=b.t){ const w=(T-a.t)/(b.t-a.t), v=a.v+(b.v-a.v)*w;
      return {v, how: w<1e-9 ? `${a.name} ${pct(a.v,3)}` : `${a.name} ${pct(a.v,3)}와 ${b.name} ${pct(b.v,3)} 사이 보간`}; } }
}
$('opt-rate-mkt').addEventListener('click',()=>{
  if(RC_USE){
    const o=state.opt, d=o.valuation;
    if(!o.maturity||!d||o.maturity<=d){ $('opt-rate-msg').innerHTML='<span class="warn">옵션계약 만기를 평가시점보다 뒤로 먼저 입력하세요.</span>'; return; }
    const osel=rcPick('opt.pick','ktb'); let g; try{ g=rcCurve(osel,d); }catch(e){ $('opt-rate-msg').innerHTML=`<span class="warn">${e.message}</span>`; return; }
    if(!g){ $('opt-rate-msg').innerHTML=`<span class="warn">공통 금리커브 자료보다 앞선 날짜입니다. 보관된 자료: ${rcRange()}</span>`; return; }
    const T=(Date.parse(o.maturity)-Date.parse(d))/864e5/365, z=CurveJS.zeroAt(g.c,T);
    o.rate_quoted=+z.toFixed(7); o.rate_comp='단리(연1회복리)';
    fillForm(); save(); recompute();
    $('opt-rate-msg').innerHTML=`<span>공통 커브 <b>${rcLabel(osel)}</b> (${rcSrcNote(g)}) · 잔존만기 T=${T.toFixed(2)}년 제로금리 <b>${pct(z,3)}</b> (연복리)를 넣었습니다.</span><span class="hint">부트스트랩한 제로금리라 만기수익률을 그대로 쓰는 기존 방식보다 할인에 더 맞는 값입니다.</span>`;
    return;
  }
  const o=state.opt, d=o.valuation, i=lookupIdx(MARKET.krw,d);
  if(!d||i<0){ $('opt-rate-msg').innerHTML=`<span class="warn">내장 시장금리는 ${first(MARKET.krw)} ~ ${last(MARKET.krw)} 기간만 있습니다. 평가시점을 이 기간 안으로 두거나 금리를 직접 입력하세요.</span>`; return; }
  if(!o.maturity||o.maturity<=d){ $('opt-rate-msg').innerHTML='<span class="warn">옵션계약 만기를 평가시점보다 뒤로 먼저 입력하세요.</span>'; return; }
  const T=(Date.parse(o.maturity)-Date.parse(d))/864e5/365, rf=rfForT(MARKET.krw.rates[i],T);
  o.rate_quoted=+rf.v.toFixed(7); o.rate_comp = T<1 ? '단리(연1회복리)' : '연 2회 복리';
  fillForm(); save(); recompute();
  $('opt-rate-msg').innerHTML=`<span>${MARKET.krw.dates[i]} 기준 · 잔존만기 T=${T.toFixed(2)}년 → ${rf.how} = <b>${pct(rf.v,3)}</b> (${o.rate_comp})</span>`+
    `${MARKET.krw.dates[i]!==d?`<span class="hint">${d}에 고시값이 없어 직전 영업일 값을 썼습니다.</span>`:''}<span class="hint">출처: 한국은행 ECOS 시장금리. 국고채 금리는 만기수익률이라 제로금리와 수 bp 차이가 날 수 있습니다.</span>`;
});
function optParams(){
  const o=state.opt, direct=o.vol_mode==='직접 입력';
  const h = direct ? null : OptionJS.histVol(o.prices||[], o.vol_freq, o.vol_n);
  const sigma = direct ? +o.sigma_direct : h.sigma;
  return { p:{valuation:o.valuation, maturity:o.maturity, spot:+o.spot, strike:+o.strike, strike_mode:o.strike_mode, strike_irr:+o.strike_irr,
             kind:o.kind, style:o.style, step:o.step, rate_quoted:+o.rate_quoted, rate_comp:o.rate_comp, sigma, quantity:(+o.quantity>0?+o.quantity:1)}, h };
}
function validateOpt(o){
  if(!o.valuation||!o.maturity) return '평가시점과 만기를 입력하세요.';
  if(o.maturity<=o.valuation) return '만기는 평가시점보다 뒤여야 합니다.';
  if(!(+o.spot>0)) return '주가를 입력하세요.';
  if(!(+o.strike>0)) return '행사가격을 입력하세요.';
  if(!(+o.quantity>0)) return '계약수량을 입력하세요 (0보다 큰 수).';
  if(o.vol_mode==='직접 입력' && !(+o.sigma_direct>0)) return '주가 변동성을 입력하세요.';
  return '';
}
// 주가 변동성: 입력한 쪽으로 입력 방식 자동 전환
