const pBase=el=>el.dataset.abs?(+state.prs[el.dataset.abs]||0)*100:0; // 절대값 슬라이더(주가 변동성): 표시값 = 기준값 + 변화분
function syncPShift(){ PSV.forEach(s=>{ const el=$('prs-sim-'+s.k); if(!el) return; el.value=pBase(el)+pshift[s.k]; $('prs-sim-'+s.k+'-out').textContent=s.fmt(pshift[s.k]); const v=$('prs-sim-'+s.k+'-val'); if(v) v.innerHTML=nwrap(pVal(s.k)); }); }
