  const step=()=>{ const b=pBase(el), v=Math.max(+el.min,Math.min(+el.max,Math.round((b+pshift[key]+d)*100)/100))-b; if(Math.abs(v-pshift[key])<1e-9) return; pshift[key]=Math.round(v*1000)/1000; syncPShift(); scheduleFast(); };
