function prsTerm(a,b){ if(!a||!b||b<=a) return '–'; const [y1,m1,d1]=a.split('-').map(Number), [y2,m2,d2]=b.split('-').map(Number);
  let mo=(y2-y1)*12+(m2-m1), dd=d2-d1; if(dd<0){ mo--; dd+=new Date(Date.UTC(y2,m2-1,0)).getUTCDate(); }
  const days=Math.round((Date.parse(b)-Date.parse(a))/864e5), Y=Math.floor(mo/12), M=mo%12;
  return `${Y?Y+'년 ':''}${M?M+'개월 ':''}${dd?dd+'일 ':''}`.trim()+` (${nf0.format(days)}일 · ${(days/365).toFixed(2)}년)`; }
