function validatePrs(p){
  if(!p.valuation||!p.start) return '평가기준일과 계약개시일을 입력하세요.';
  if(p.valuation<p.start) return '평가기준일이 계약개시일보다 앞섭니다.';
  if(!p.maturity) return '계약만료일을 입력하세요.';
  if(p.maturity<=p.start) return '계약만료일이 계약개시일보다 뒤여야 합니다.';
  if(p.valuation>=p.maturity) return '평가기준일이 계약만료일 이후입니다.';
  if(!(p.notional>0)) return '계약금액을 입력하세요.';
  if(!(p.usd_equity>0&&p.stake>0&&p.fx>0)) return 'USD 지분가치·지분율·환율을 입력하세요.';
  if(!(p.vol>0)) return '주가 변동성을 입력하세요.';
  if(p.gov_ytm[0]==null||p.aa_ytm[0]==null) return `${PRSN().gov}·${PRSN().aa} 3M YTM은 비워둘 수 없습니다.`;
  if(!(p.gap_days>=1&&p.max_steps>=10)) return '트리 간격과 최대 Step 수를 확인하세요.';
  return '';
}
let PRS_CACHE={key:null,res:null,gov:null,aa:null,ckey:null};
function barChart(rows,{yfmt,height=200,hmul=null,w=null,labels=null,xlab=null,ylab=null}={}){
  const z=FZ(), W=w||CW(), H=Math.round(height*(hmul||(WIDE.matches?2.9:1.4))+(ylab?20*z:0)+(xlab?20*z:0)), L=Math.round(66*z), R=Math.round(14*z), T=Math.round((ylab?32:12)*z), B=Math.round((xlab?50:30)*z);
  if(!rows.length) return '';
  const ys=rows.map(r=>r.v).concat([0]), yt=niceTicks(Math.min(...ys),Math.max(...ys)), y0=yt[0], y1=yt[yt.length-1];
  const sy=y=>T+(1-(y-y0)/((y1-y0)||1))*(H-T-B), bw=(W-L-R)/rows.length;
  const id=lcReg({kind:'bar',W,H,L,R,T,B,y0,y1,bw,yfmt,rows:rows.map(r=>({v:r.v,lab:r.lab,c:r.color||'var(--neg)'}))});
  let g='';
  yt.forEach(v=>{ g+=`<line class="gl" x1="${L}" x2="${W-R}" y1="${sy(v)}" y2="${sy(v)}"/><text x="${L-6*z}" y="${sy(v)+4*z}" text-anchor="end">${yfmt(v)}</text>`; });
  const every=Math.ceil(rows.length/4);
  rows.forEach((r,i)=>{ const x=L+i*bw, top=sy(Math.max(0,r.v)), h=Math.abs(sy(r.v)-sy(0));
    g+=`<rect x="${(x+bw*0.15).toFixed(1)}" y="${top.toFixed(1)}" width="${(bw*0.7).toFixed(1)}" height="${Math.max(1,h).toFixed(1)}" rx="2" fill="${r.color||'var(--neg)'}" fill-opacity="${r.dim?0.35:0.85}"/>`;
    if(labels){ const fs=Math.min(bw*0.6,13*z), cx=(x+bw/2+fs*0.35).toFixed(1), inside=h>fs*4.2;
      g+=`<text transform="translate(${cx},${(inside?top+5*z:top-5*z).toFixed(1)}) rotate(-90)" text-anchor="${inside?'end':'start'}" style="font-size:${fs.toFixed(1)}px;font-weight:600;fill:${inside?'#fff':'var(--ink)'}">${labels(r.v)}</text>`; }
    if(i%every===0) g+=`<text x="${(x+bw/2).toFixed(1)}" y="${H-B+23*z}" text-anchor="middle">${r.lab}</text>`; });
  if(ylab) g+=`<text class="ax" x="2" y="${T-12*z}" text-anchor="start">↑ ${ylab}</text>`;
  if(xlab) g+=`<text class="ax" x="${(L+W-R)/2}" y="${H-5*z}" text-anchor="middle">${xlab} →</text>`;
  g+=`<line class="zl" x1="${L}" x2="${W-R}" y1="${sy(0)}" y2="${sy(0)}" style="stroke-width:1.5px"/>`;
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" data-lc="${id}">${g}</svg>`;
}
