  // ── 변동 정산분 양(+)·음(−) 분해
  { const bp0=res.B_pos, bn0=res.B_neg, bp1=cur.B_pos, bn1=cur.B_neg, wt=cur.tax_ded>0?' (세후)':'';
    $('prs-bpn-cap').innerHTML=`만기 정산분 S·(1−비용) − K를 <b>양수 부분</b>(주가가 올라 받는 금액)과 <b>음수 부분</b>(주가가 내려 주는 금액)으로 나눠 같은 트리·확률·할인율로 현재가치했습니다. 둘을 더하면 B입니다. 지금 시나리오에서 양(+) 정산 확률 q는 <b>${pct(cur.q0,1)}</b>입니다.`+(cur.tax_ded>0?' 양도차익 세금이 수령자 부담이라 양수 부분은 세후 금액입니다.':'');
    const tr=(lab,a,b,c)=>`<tr${c?' class="cur"':''}><td>${lab}</td><td class="${a>=0?'pos':'neg'}">${milS(a)}</td><td class="${b>=0?'pos':'neg'}">${milS(b)}</td><td class="${b-a>=0?'pos':'neg'}">${milS(b-a)}</td></tr>`;
    $('prs-bpn-tbl').innerHTML='<table><thead><tr><th>구분 (백만원)</th><th>기준</th><th>시나리오</th><th>변화</th></tr></thead><tbody>'+
      tr('양(+) 정산분 PV (수취)'+wt,bp0,bp1)+tr('음(−) 정산분 PV (지급)',bn0,bn1)+tr('B 변동수익 정산분 (합계)',res.B,cur.B,true)+'</tbody></table>'; }
  bchart($('prs-wf'),[Math.min(0,fv,s1.fv,s2.fv,s3.fv,s4.fv,cur.fv),Math.max(0,fv,s1.fv,s2.fv,s3.fv,s4.fv,cur.fv)],[
    {id:'0',lab:'기준<br>공정가치',from:0,to:fv,color:'var(--muted)',txt:bS(fv)},
    {...step('주가<br>'+PSV[0].fmt(pshift.eq),fv,s1.fv),id:'1',link:true},
    {...step('환율<br>'+PSV[1].fmt(pshift.fx),s1.fv,s2.fv),id:'2',link:true},
    {...step('주가 변동성<br>'+PSV[2].fmt(pshift.v),s2.fv,s3.fv),id:'v',link:true},
    {...step('금리<br>'+fmtBp(pshift.r),s3.fv,s4.fv),id:'3',link:true},
    {...step('Premium<br>'+PSV[3].fmt(pshift.pr),s4.fv,cur.fv),id:'pr',link:true},
    {id:'4',lab:'시나리오<br>공정가치',from:0,to:cur.fv,color:'var(--accent)',txt:bS(cur.fv)}],true,null,'공정가치 (눈금: 억원)');
  // 금리커브 (시나리오 금리 반영)
  const sh=pshift.r/10000, cv=cur.curve;
  $('prs-curve').innerHTML=(p.model==='crr'?'<ul class="key"><li><i class="lg-line" style="border-color:var(--accent)"></i>국고채 spot (위험중립확률·트리 할인·고정수익 할인 — 순수 CRR)</li><li><i class="lg-line" style="border-color:var(--usd)"></i>'+PRSN().aa+' spot (순수 CRR에서는 할인에 쓰지 않음, 참고용)</li></ul>':'<ul class="key"><li><i class="lg-line" style="border-color:var(--accent)"></i>국고채 spot (위험중립확률·q 할인)</li><li><i class="lg-line" style="border-color:var(--usd)"></i>회사채 AA- spot (고정수익·(1−q) 할인)</li></ul>')+
    lineChart([{color:'var(--accent)',pts:cv.t.map((t,i)=>[t,cv.gov[i]+sh])},{color:'var(--usd)',pts:cv.t.map((t,i)=>[t,cv.aa[i]+sh])}],
      {yfmt:v=>(v*100).toFixed(2)+'%',xfmt:v=>v+'년',xmin:0,xmax:10,height:170,xlab:'만기 (년)',ylab:'spot 금리 (연복리)',...(WIDE.matches?{w:600,hmul:1.75}:{})})+
    (pshift.r?`<p class="cap">금리 평행이동 ${fmtBp(pshift.r)}가 반영된 커브입니다.</p>`:'');
  const live=cur.rows.filter(r=>r.live);
