let CB_CACHE={key:null,res:null,ckey:null,gov:null};
function cVal(k){
  const s=state.cb, w=v=>`<span class="nw">${v}</span>`;
  if(k==='s'){ const S=+s.spot; return S>0?`주가 ${w(`<b>${nf0.format(S)}</b> → <b>${nf0.format(S*(1+cshift.s/100))}</b>원`)}`:''; }
  if(k==='v'){ const v=+s.vol; return isFinite(v)?`주가 변동성 σ ${w(`<b>${pct(v,1)}</b> → <b>${pct(Math.max(0.0001,v+cshift.v/100),1)}</b>`)}`:''; }
  if(k==='r'){ const g=CB_CACHE.gov, r=CB_CACHE.res; if(!g||!r) return ''; const T=r.T, at=(sp,t)=>{ if(t<=0.25) return sp[0]; if(t>=10) return sp[39]; const k=Math.floor(t*4); return sp[k-1]+(t*4-k)*(sp[k]-sp[k-1]); };
    const z=at(g.spot,T), f=v=>(v*100).toFixed(2); return `만기 국고채 spot ${w(`<b>${f(z)}</b>→<b>${f(z+cshift.r/1e4)}%</b>`)}`; }
  if(k==='c'){ const c=+s.credit_spread; return isFinite(c)?`신용스프레드 ${w(`<b>${(c*1e4).toFixed(0)}</b> → <b>${(c*1e4+cshift.c).toFixed(0)}</b>bp`)}`:''; }
  return '';
}
function syncCShift(){ CSV.forEach(s=>{ const el=$('cb-sim-'+s.k); if(!el) return; el.value=cshift[s.k]; $('cb-sim-'+s.k+'-out').textContent=s.fmt(cshift[s.k]); const v=$('cb-sim-'+s.k+'-val'); if(v) v.innerHTML=cVal(s.k); }); }
document.querySelectorAll('input[data-cshift]').forEach(el=>el.addEventListener('input',()=>{ cshift[el.dataset.cshift]=+el.value; syncCShift(); scheduleFast(); }));
document.querySelectorAll('.cnudge').forEach(btn=>{
  const el=$(btn.dataset.for), key=el.dataset.cshift, d=+btn.dataset.nudge*(+el.step||1); let t1=0,t2=0;
  const step=()=>{ const v=Math.max(+el.min,Math.min(+el.max,Math.round((cshift[key]+d)*100)/100)); if(v===cshift[key]) return; cshift[key]=v; syncCShift(); scheduleFast(); };
  const stop=()=>{ clearTimeout(t1); clearInterval(t2); t1=t2=0; };
  btn.addEventListener('pointerdown',e=>{ e.preventDefault(); stop(); step(); t1=setTimeout(()=>{ t2=setInterval(step,70); },400); });
  ['pointerup','pointerleave','pointercancel','blur'].forEach(ev=>btn.addEventListener(ev,stop));
  btn.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); step(); } });
  btn.addEventListener('contextmenu',e=>e.preventDefault());
});
