if(!state.cb.rate_vol_mode) state.cb.rate_vol_mode='fixed';
const rvmGet=()=>{ const m=state.cb.rate_vol_matrix; return Array.isArray(m)&&m.length===RVM_EXP.length?m:RVM_EXP.map(()=>RVM_TEN.map(()=>'')); };
const rvmNum=v=>{ if(v==null) return null; const t=String(v).replace(/[%,\s]/g,''); if(t==='') return null; const x=+t; return isFinite(x)&&x>0?x:null; };
// 빈칸 채우기: 같은 행(스왑기간 방향) 선형보간·끝값 → 값이 하나도 없는 행은 옵션만기 방향 보간
function rvmFilled(){
  const g=rvmGet().map(r=>r.map(rvmNum)); if(!g.some(r=>r.some(v=>v!=null))) return null;
  const fillLine=(xs,ys)=>{ const pts=xs.map((x,i)=>[x,ys[i]]).filter(p=>p[1]!=null); if(!pts.length) return null;
    return xs.map(x=>{ if(x<=pts[0][0]) return pts[0][1]; if(x>=pts[pts.length-1][0]) return pts[pts.length-1][1];
      for(let k=0;k<pts.length-1;k++){ const [a,ya]=pts[k],[b,yb]=pts[k+1]; if(a<=x&&x<=b) return ya+(yb-ya)*(x-a)/(b-a); } }); };
  const rows=g.map(r=>fillLine(RVM_TY,r));
  const out=RVM_TY.map((_,j)=>fillLine(RVM_EY,rows.map(r=>r?r[j]:null)));
  return {exp:RVM_EY, ten:RVM_TY, vol:RVM_EY.map((_,i)=>RVM_TY.map((_,j)=>+out[j][i].toFixed(6)))};
}
$('cb-rvm-tbl').innerHTML='<table><thead><tr><th title="행: 옵션만기 · 열: 스왑기간">만기＼기간</th>'+RVM_TEN.map(t=>`<th>${t}</th>`).join('')+'</tr></thead><tbody>'+
  RVM_EXP.map((e,i)=>`<tr><th>${e}</th>`+RVM_TEN.map((t,j)=>`<td><input type="text" inputmode="decimal" autocomplete="off" data-rvm="${i}:${j}" aria-label="금리 변동성 ${e}×${t} (%)"></td>`).join('')+'</tr>').join('')+'</tbody></table>';
function rvmSet(i,j,v){ const m=rvmGet().map(r=>r.slice()); m[i][j]=v; state.cb.rate_vol_matrix=m; }
function syncRvm(){
  const on=state.cb.rate_vol_mode==='matrix', m=rvmGet();
  $('cb-rvm-btn').setAttribute('aria-pressed',on); $('cb-rvm-btn').textContent=on?'매트릭스 사용 중 · 누르면 고정값으로':'금리 변동성 매트릭스 입력하기';
  $('cb-rvm-btn').closest('.rvm-box').classList.toggle('off',!on);
  $('cb-rate_vol').disabled=on; $('cb-rv-tag').textContent=on?'(매트릭스 사용 중 · 미적용)':'(고정값 · 모든 기간에 적용)';
  document.querySelectorAll('[data-rvm]').forEach(el=>{ el.disabled=!on; if(document.activeElement===el) return; const [i,j]=el.dataset.rvm.split(':').map(Number); const v=m[i][j]; el.value=v==null?'':v; });
  $('cb-rvm-h').innerHTML=on?'블룸버그 스왑션 변동성 화면을 <b>Black(로그정규, %)</b>로 놓고 값을 넣으세요. 엑셀이나 단말기에서 표를 복사해 아무 칸에 붙여넣으면 그 칸부터 채워집니다(머리글 행·열은 자동으로 건너뜀). 빈칸은 같은 행에서 보간합니다.<br>적용 방식: 트리 스텝마다 그 시점을 옵션만기로, 사채 만기까지 남은 기간을 스왑기간으로 보는 칸(co-terminal)을 보간해 그 스텝의 금리 변동성으로 씁니다.'
    :'지금은 위 <b>금리 변동성 σr</b> 고정값을 모든 기간에 씁니다. 스왑션 변동성 매트릭스를 쓰려면 오른쪽 버튼을 누르세요.';
}
$('cb-rvm-btn').addEventListener('click',()=>{
  const on=state.cb.rate_vol_mode!=='matrix'; state.cb.rate_vol_mode=on?'matrix':'fixed';
  if(on&&!rvmGet().some(r=>r.some(v=>rvmNum(v)!=null))){ const f=+(+state.cb.rate_vol*100).toFixed(4); state.cb.rate_vol_matrix=RVM_EXP.map(()=>RVM_TEN.map(()=>f)); }
  syncRvm(); save(); schedule();
});
$('cb-rvm-fill').addEventListener('click',()=>{ const f=+(+state.cb.rate_vol*100).toFixed(4); state.cb.rate_vol_matrix=RVM_EXP.map(()=>RVM_TEN.map(()=>f)); syncRvm(); save(); schedule(); });
$('cb-rvm-clear').addEventListener('click',()=>{ state.cb.rate_vol_matrix=RVM_EXP.map(()=>RVM_TEN.map(()=>'')); syncRvm(); save(); schedule(); });
document.querySelectorAll('[data-rvm]').forEach(el=>{
  el.addEventListener('input',()=>{ const [i,j]=el.dataset.rvm.split(':').map(Number); rvmSet(i,j,el.value.trim()); save(); schedule(); });
  el.addEventListener('paste',e=>{
    const txt=(e.clipboardData||window.clipboardData).getData('text'); if(!txt||!/[\t\n]/.test(txt)) return;
    e.preventDefault();
    let rows=txt.replace(/\r/g,'').split('\n').filter(r=>r.trim()!=='').map(r=>r.split(/\t|,|\s{2,}/).map(c=>c.trim()));
    const isNum=c=>rvmNum(c)!=null;
    if(rows.length&&!rows[0].some(isNum)) rows=rows.slice(1);                       // 머리글 행
    if(rows.length&&rows.every(r=>r.length&&!isNum(r[0]))) rows=rows.map(r=>r.slice(1)); // 머리글 열
    const [i0,j0]=el.dataset.rvm.split(':').map(Number), m=rvmGet().map(r=>r.slice()); let n=0;
    rows.forEach((r,di)=>r.forEach((c,dj)=>{ const i=i0+di, j=j0+dj; if(i<RVM_EXP.length&&j<RVM_TEN.length){ m[i][j]=rvmNum(c)==null?'':String(+rvmNum(c).toFixed(4)); n++; } }));
    state.cb.rate_vol_matrix=m; syncRvm(); save(); schedule();
    $('cb-rvm-out').textContent=`${n}칸을 붙여넣었습니다.`;
  });
});
