function validateCb(p){
  if(!p.valuation||!p.issue||!p.maturity) return '평가일·발행일·만기일을 입력하세요.';
  if(p.maturity<=p.valuation) return '만기일은 평가일보다 뒤여야 합니다.';
  if(p.valuation<p.issue) return '평가일은 발행일 이후여야 합니다.';
  if(!(p.face_total>0)) return '권면총액을 입력하세요.';
  if(p.put_on&&!p.put_start) return '조기상환 최초 청구일을 입력하세요.';
  if(p.call_on&&(!p.call_start||!p.call_end)) return '매도청구권 행사기간을 입력하세요.';
  if(p.kind!=='SB'){ if(!(p.spot>0)) return '주가를 입력하세요.'; if(!(p.conv_price>0)) return CB_KIND[p.kind].cp.replace(' (원)','')+'을 입력하세요.'; if(!(p.vol>0)) return '주가 변동성을 입력하세요.'; }
  if(!p.gov_ytm.some(v=>v!=null)) return '국고채 YTM을 하나 이상 입력하세요.';
  if(p.rate_vol_mode==='matrix'&&!p.rate_vol_matrix) return '금리 변동성 매트릭스에 값을 하나 이상 입력하세요. (고정값을 쓰려면 매트릭스 입력을 끄세요)';
  return '';
}
