  const vd=Date.parse(p.valuation), dstr=t=>{ const d=new Date(vd+Math.round(t*365)*864e5); return `${String(d.getUTCFullYear()).slice(2)}.${String(d.getUTCMonth()+1).padStart(2,'0')}`; };
  const fl=res.flows;
