  cr.push([],['입력 국고채 YTM (%)'],['만기'].concat(q.gov_ytm.length===8?CB_LABELS_V1:CB_LABELS),['YTM'].concat(q.gov_ytm.map(v=>v==null?'':v)));
  XLSX.utils.book_append_sheet(wb, sheet(cr,[10,14,14]), '금리커브');
  if(q.rate_vol_mode==='matrix'&&q.rate_vol_matrix){ const mm=q.rate_vol_matrix;
    const rv=[['금리 변동성 매트릭스 (스왑션 Black 변동성, %) — 빈칸은 보간한 값'],[],['옵션만기 \\ 스왑기간'].concat(RVM_TEN)].concat(RVM_EXP.map((e,i)=>[e].concat(mm.vol[i].map(v=>n(v,'0.00')))));
    rv.push([],['스텝별 적용 금리 변동성 (옵션만기 = 스텝 시점, 스왑기간 = 만기까지 남은 기간)'],['스텝','t (년)','σ']);
    (r.rate_sigs||[]).forEach((x,i)=>rv.push([i,n(x.t,'0.0000'),n(x.sigma,'0.00%')]));
    XLSX.utils.book_append_sheet(wb, sheet(rv,[18,10,10,10,10,10,10]), '금리변동성'); }
  const w=L.wf.map(v=>v*r.units), sm=[['■ 슬라이더 효과 (폭포, 총액 원)','공정가치','변화'],['기준',n(w[0],W),null],['주가',n(w[1],W),n(w[1]-w[0],W)],['주가 변동성',n(w[2],W),n(w[2]-w[1],W)],['금리',n(w[3],W),n(w[3]-w[2],W)],['신용스프레드',n(w[4],W),n(w[4]-w[3],W)],[]];
  if(L.prof){ sm.push(['■ 주가에 따른 가치 (총액 원)'],['주가','공정가치','사채 가치','패리티(최초가)']); L.prof.forEach(x=>sm.push([n(x.S,W),n(x.v*r.units,W),n(x.host*r.units,W),n(x.par*r.units,W)])); }
  XLSX.utils.book_append_sheet(wb, sheet(sm,[30,16,16,16]), '시뮬레이션');
