/* ── tabs ── */
const tabs=[...document.querySelectorAll('nav.tabs button')];
function selectTab(t){ tabs.forEach(b=>b.setAttribute('aria-selected', b.dataset.tab===t)); { const nv=document.querySelector('nav.tabs'); if(nv) nv.style.setProperty('--ti', Math.max(0,tabs.findIndex(b=>b.dataset.tab===t))); } ['irs','crs','curve'].forEach(k=>$('panel-'+k).hidden=k!==t); try{localStorage.setItem('swapvaluer.tab',t)}catch(e){} }
tabs.forEach(b=>b.addEventListener('click',()=>selectTab(b.dataset.tab)));
const HASH=location.hash.slice(1);
let startTab=['irs','crs','curve'].includes(HASH)?HASH:null; if(!startTab){ try{ startTab=localStorage.getItem('swapvaluer.tab') }catch(e){} }
selectTab(['irs','crs','curve'].includes(startTab)?startTab:'irs');
let startView = ['irs','crs','curve','swap'].includes(HASH)?'swap' : ['option','opt'].includes(HASH)?'option' : HASH==='prs'?'prs' : HASH==='cb'?'cb' : HASH==='fx'?'fx' : HASH==='fin'?'fin' : HASH==='rates'?'rates' : HASH==='home'?'home' : null;
if(!startView){ try{ startView=localStorage.getItem('swapvaluer.view'); }catch(e){} }
VIEW=VIEWS.includes(startView)?startView:'home';
VIEWS.forEach(k=>$('view-'+k).hidden=k!==VIEW); $('home-btn').hidden=VIEW==='home'; $('maker-calc').hidden=VIEW==='home';
$('app-title').textContent = TITLE(VIEW); $('app-kicker').textContent = VIEW==='home'?'Valuation Toolkit':'Financial Calculator';
syncOShift(); syncPShift(); syncCShift(); syncFShift();



hookCharts(); fillForm(); recompute(); setChip('py','Rust 엔진 '+ENGINE_VERSION+' 계산 중 (WebAssembly)');
